mapper.insert:
insert into lims_audit_trail(
    table_name, record_id, field_name, old_value, new_value,
    operation_type, operator_id, operator_name, operation_time,
    reason, signature_id, ip_address, application_name, session_id
)values(
    #{tableName}, #{recordId}, #{fieldName}, #{oldValue}, #{newValue},
    #{operationType}, #{operatorId}, #{operatorName}, #{operationTime},
    #{reason}, #{signatureId}, #{ipAddress}, #{applicationName}, #{sessionId}
)

mapper.select:
select audit_id, table_name, record_id, field_name, old_value, new_value,
       operation_type, operator_id, operator_name, operation_time,
       reason, signature_id, ip_address, application_name, session_id
from lims_audit_trail

     and table_name = #{tableName}
     and record_id = #{recordId}
     and operation_type = #{operationType}
     and operator_id = #{operatorId}

order by operation_time desc
